#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD1=998244353,MOD2=1e9+7;
const int MAXN=2e6,MAX=1e6;
ll n_value,c_value;
int total,ans,lim,pw[MAXN],sum[MAXN];
vector<int> v[MAXN];

inline int dec(int x,int y,int m){return (x-y<0)?x-y+m:x-y;}
inline int add(int x,int y,int m){return (x+y>=m)?x+y-m:x+y;}
inline void dfs(int pos,int now){
	if(now<=n_value){
		++total;int x=dec(total,now,MOD1);
		v[pos-1].push_back(x);sum[pos-1]=add(sum[pos-1],x,MOD2);
	}
	if(pos>6) return ;
	for(int i=0;i<=9;++i) dfs(pos+1,now*10+i);
}
inline void solve(int pos,ll now){
	if(now>n_value) return ;
	if(pos>1){
		if(10ll*now*MAX>n_value&&1ll*(now+1)*MAX-1<=n_value){
			for(int i=0;i<7;++i){
				int x=((c_value-1ll*now*pw[i])%MOD1+MOD1)%MOD1;
				int p=lower_bound(v[i].begin(),v[i].end(),MOD1-x)-v[i].begin();
				ans=add(ans,add(1ll*x*v[i].size()%MOD2,sum[i],MOD2),MOD2);
				ans=dec(ans,1ll*MOD1*(v[i].size()-p)%MOD2,MOD2);
			}
			c_value+=total;
			return ;
		}
		++c_value;ans=add(ans,((c_value-now)%MOD1+MOD1)%MOD1,MOD2);
	}
	for(int i=(pos==1?1:0);i<=9;++i) solve(pos+1,now*10+i);
}
int main(){
	scanf("%lld",&n_value);
	pw[0]=1;for(int i=1;i<9;++i) pw[i]=10*pw[i-1];
	dfs(1,0);
	for(int i=0;i<7;++i)
		sort(v[i].begin(),v[i].end()); 
	solve(1,0);
	printf("%d\n",ans);
	return 0;
}
